@Dao
interface OrderDao {
    @Query("SELECT * FROM orders ORDER BY createdAt DESC")
    fun getOrdersFlow(): Flow<List<OrderEntity>>

    @Upsert
    suspend fun upsertOrders(orders: List<OrderEntity>)
}

class OrderRepository(
    private val orderDao: OrderDao,
    private val apiService: OrderApiService
) {
    val orders: Flow<List<Order>> = orderDao.getOrdersFlow()
        .map { entities -> entities.map { it.toDomainModel() } }
        .distinctUntilChanged()

    suspend fun refreshOrders(): Result<Unit> = runCatching {
        val networkOrders = apiService.fetchLatestOrders()
        orderDao.upsertOrders(networkOrders.map { it.toEntity() })
    }
}
